/**
 * Writes the example islands of the catalog to `website/src/generated/examples/` (git-ignored):
 * per entry, `<slug>.tsx`, the island module, which imports that entry's one story file (its meta
 * and its stories by name) and calls `createExampleIsland`, and `<slug>.astro`, which renders it
 * `client:visible`. `Example.astro` picks the wrapper of its slug.
 *
 * Why generated files: Astro hydrates only a component imported statically by an `.astro` file
 * (a dynamic tag gets no client entry), and a page must hold only its own stories in its client
 * code (ruling of Task 4: islands never call `loadStory`, whose map makes every story file a lazy
 * chunk of the island, 447 KiB gzipped). One static import per entry gives each page one story
 * file; generating the 160 small files from the catalog keeps them from drifting from the stories.
 *
 * The site's Astro configuration runs {@link writeExampleIslands} when it loads (`astro build`,
 * `astro dev` and the Vitest projects alike), through Vite's module runner, since this module and
 * the catalog are TypeScript. It writes only the files whose content changed and removes the
 * files of entries that are gone. Build-time code; never sent to the browser.
 */
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { getCatalog, type ComponentEntry } from '../catalog/catalog';
import { REPO_ROOT } from '../repoRoot';

export interface GeneratedFile {
  /** The file name inside the output directory (`button.tsx`). */
  path: string;
  content: string;
}

/** The output directory, from the repository root. */
export const EXAMPLE_ISLANDS_DIR = 'website/src/generated/examples';

const HEADER =
  'Generated by website/src/examples/islands.ts from the catalog when the site config loads: do not edit.';

/** Names the island module binds itself, which no story may take. */
const RESERVED = new Set(['meta', 'createExampleIsland', 'default']);

/** Every catalog entry's island module and wrapper. `skipped` lists `<storyFile>#<ExportName>`. */
export function exampleIslandFiles(
  entries: readonly Pick<ComponentEntry, 'slug' | 'storyFile' | 'storyNames'>[],
  skipped: readonly string[],
): GeneratedFile[] {
  return entries.flatMap((entry) => {
    const stories = entry.storyNames.filter(
      (name) => !skipped.includes(`${entry.storyFile}#${name}`),
    );
    for (const name of stories) {
      if (RESERVED.has(name)) {
        throw new Error(
          `The story ${entry.storyFile}#${name} takes a name the example island binds`,
        );
      }
    }
    const specifier = `../../../../${entry.storyFile.replace(/\.tsx$/, '')}`;
    const named = stories.length > 0 ? `, { ${stories.join(', ')} }` : '';
    const island = [
      `// ${HEADER}`,
      `import meta${named} from '${specifier}';`,
      `import { createExampleIsland } from '../../islands/Example';`,
      '',
      `export default createExampleIsland('${entry.storyFile}', { default: meta${stories.map((name) => `, ${name}`).join('')} });`,
      '',
    ].join('\n');
    const wrapper = [
      '---',
      `// ${HEADER}`,
      `import Island from './${entry.slug}.tsx';`,
      '---',
      '',
      '<Island client:visible {...Astro.props} />',
      '',
    ].join('\n');
    return [
      { path: `${entry.slug}.tsx`, content: island },
      { path: `${entry.slug}.astro`, content: wrapper },
    ];
  });
}

function readSkipped(): string[] {
  const file = join(REPO_ROOT, 'website/skipped-stories.json');
  return (JSON.parse(readFileSync(file, 'utf8')) as { story: string }[]).map((item) => item.story);
}

/**
 * Writes the islands of the catalog to `outDir`: the files whose content changed, and removes the
 * others. Returns what it wrote and removed.
 */
export function writeExampleIslands(outDir: string = join(REPO_ROOT, EXAMPLE_ISLANDS_DIR)): {
  written: string[];
  removed: string[];
} {
  const files = exampleIslandFiles(getCatalog(), readSkipped());
  mkdirSync(outDir, { recursive: true });
  const written: string[] = [];
  for (const file of files) {
    const target = join(outDir, file.path);
    if (existsSync(target) && readFileSync(target, 'utf8') === file.content) continue;
    writeFileSync(target, file.content);
    written.push(file.path);
  }
  const keep = new Set(files.map((file) => file.path));
  const removed = readdirSync(outDir).filter((name) => !keep.has(name));
  for (const name of removed) rmSync(join(outDir, name), { recursive: true, force: true });
  return { written, removed };
}
